<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { api, upload } from '../api.js';
const props = defineProps({ path: String });
const id = computed(() => props.path.split('/')[1] || '');
const skills = ref([]), detail = ref(null), error = ref(''), notice = ref(''), busy = ref(false), source = ref('local'), zip = ref(null);
const scripts = ref([]), script = ref(''), scriptArgs = ref('[]'), scriptInput = ref(''), scriptJob = ref(null);
const form = reactive({ path: '', url: '', branch: 'main', subpath: '', name: '', description: '', content: '' });
async function load() {
  error.value = '';
  try {
    skills.value = await api('/api/skills');
    if (id.value && id.value !== 'new') { detail.value = await api(`/api/skills/${id.value}`); scripts.value = await api(`/api/skills/${id.value}/scripts`); Object.assign(form, detail.value.view, { content: detail.value.content }); }
  } catch (e) { error.value = e.message; }
}
async function install() {
  busy.value = true; error.value = '';
  try {
    let result;
    if (source.value === 'local') result = await api('/api/skills/install/local', { method: 'POST', body: { path: form.path } });
    else if (source.value === 'github') result = await api('/api/skills/install/github', { method: 'POST', body: { url: form.url, branch: form.branch, subpath: form.subpath } });
    else { if (!zip.value) throw new Error('请选择 ZIP 文件'); const body = new FormData(); body.append('file', zip.value); body.append('subpath', form.subpath); result = await upload('/api/skills/install/zip', body); }
    location.hash = `#/skills/${result.view.id}`;
  } catch (e) { error.value = e.message; } finally { busy.value = false; }
}
async function save() { busy.value = true; error.value = ''; try { detail.value = await api(`/api/skills/${id.value}`, { method: 'PUT', body: { name: form.name, description: form.description, content: form.content } }); notice.value = '技能已更新，进行中的任务继续使用原版本。'; } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function enabled(item) { try { await api(`/api/skills/${item.id}/enabled`, { method: 'POST', body: { enabled: !item.enabled } }); await load(); } catch (e) { error.value = e.message; } }
async function refresh() { busy.value = true; try { detail.value = await api(`/api/skills/${id.value}/refresh`, { method: 'POST' }); scripts.value = await api(`/api/skills/${id.value}/scripts`); Object.assign(form, detail.value.view, { content: detail.value.content }); notice.value = '已从 GitHub 更新'; } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function remove(item) { if (!window.confirm(`卸载技能“${item.name}”？`)) return; try { await api(`/api/skills/${item.id}`, { method: 'DELETE' }); location.hash = '#/skills'; await load(); } catch (e) { error.value = e.message; } }
async function runScript() { busy.value = true; error.value = ''; scriptJob.value = null; try { const args = JSON.parse(scriptArgs.value); if (!Array.isArray(args) || args.some(item => typeof item !== 'string')) throw new Error('脚本参数必须是字符串数组'); scriptJob.value = await api('/api/skill-script-runs', { method: 'POST', body: { skillId: id.value, script: script.value, args, stdin: scriptInput.value } }); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function decideScript(decision) { busy.value = true; error.value = ''; try { scriptJob.value = await api(`/api/skill-script-actions/${scriptJob.value.action.id}/${decision}`, { method: 'POST' }); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
onMounted(load);
</script>
<template>
  <main class="content-page"><template v-if="!id"><div class="page-heading"><div><p class="eyebrow">CAPABILITIES</p><h1>技能管理</h1><p class="muted">技能为默认智能体提供可复用的任务说明。</p></div><a class="primary link-button" href="#/skills/new">安装技能</a></div><p v-if="error" class="error" role="alert">{{ error }}</p><div class="resource-grid"><article v-for="item in skills" :key="item.id" class="resource-card"><div class="resource-heading"><span class="resource-icon">S</span><span class="badge">{{ item.source }}</span><span class="badge" :class="{green:item.enabled}">{{ item.enabled ? '已启用' : '已停用' }}</span></div><h2>{{ item.name }}</h2><p class="muted">{{ item.description }}</p><p class="small muted">版本 {{ item.version }}</p><div class="card-actions"><a :href="`#/skills/${item.id}`">查看详情</a><button class="text-button" @click="enabled(item)">{{ item.enabled ? '停用' : '启用' }}</button><button v-if="!item.builtin" class="text-button danger" @click="remove(item)">卸载</button></div></article></div></template>
    <template v-else-if="id === 'new'"><a class="back-link" href="#/skills">← 返回技能管理</a><div class="page-heading"><div><p class="eyebrow">INSTALL SKILL</p><h1>安装技能</h1><p class="muted">选择本地目录、ZIP 或 GitHub 仓库。</p></div></div><form class="form-card" @submit.prevent="install"><label>安装来源<select v-model="source"><option value="local">本地目录</option><option value="zip">ZIP 文件</option><option value="github">GitHub 仓库</option></select></label><label v-if="source === 'local'">本地目录绝对路径<input v-model.trim="form.path" required placeholder="包含 SKILL.md 的目录"></label><label v-if="source === 'zip'">ZIP 文件<input type="file" accept=".zip,application/zip" required @change="zip = $event.target.files[0]"></label><template v-if="source === 'github'"><label>仓库地址<input v-model.trim="form.url" type="url" required placeholder="https://github.com/owner/repository"></label><label>分支<input v-model.trim="form.branch" required></label></template><label v-if="source !== 'local'">技能子目录 <span class="muted">（可选）</span><input v-model.trim="form.subpath" placeholder="仓库或压缩包内的相对路径"></label><p class="muted small">技能包需要包含 SKILL.md。外部技能脚本需要安全隔离，当前不会自动执行。</p><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary" :disabled="busy">{{ busy ? '安装中…' : '安装技能' }}</button></form></template>
    <template v-else><a class="back-link" href="#/skills">← 返回技能管理</a><div v-if="detail" class="page-heading"><div><p class="eyebrow">SKILL DETAILS</p><h1>{{ detail.view.name }}</h1><p class="muted">{{ detail.view.source }} · 版本 {{ detail.view.version }} · {{ detail.view.enabled ? '已启用' : '已停用' }}</p></div><button v-if="detail.view.source === 'GITHUB'" class="secondary" :disabled="busy" @click="refresh">从 GitHub 更新</button></div><form v-if="detail" class="form-card" @submit.prevent="save"><label>技能名称<input v-model="form.name" :readonly="detail.view.builtin" required></label><label>说明<input v-model="form.description" :readonly="detail.view.builtin"></label><label>技能内容<textarea v-model="form.content" :readonly="detail.view.builtin" rows="18" class="mono"></textarea></label><p class="muted small">技能内容不能修改系统权限；脚本执行需安全隔离。</p><p v-if="notice" class="notice" role="status">{{ notice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><div class="form-actions"><button v-if="!detail.view.builtin" class="primary" :disabled="busy">保存修改</button><button type="button" class="secondary" @click="enabled(detail.view)">{{ detail.view.enabled ? '停用' : '启用' }}</button><button v-if="!detail.view.builtin" type="button" class="secondary danger" @click="remove(detail.view)">卸载技能</button></div></form><p v-else-if="error" class="error" role="alert">{{ error }}</p>
      <section v-if="detail && !detail.view.builtin" class="result-panel"><h2>运行技能脚本</h2><p class="muted small">脚本在受限环境运行，不能访问网络或写入宿主文件；每次运行都需要你确认。</p><p v-if="!scripts.length" class="quiet-state">技能包中没有可运行的 Python 或 Node 脚本。</p><form v-else @submit.prevent="runScript"><label class="search-label">脚本<select v-model="script" required><option value="" disabled>选择脚本</option><option v-for="item in scripts" :key="item" :value="item">{{ item }}</option></select></label><label class="search-label">参数（JSON 字符串数组）<textarea v-model="scriptArgs" rows="3" class="mono"></textarea></label><label class="search-label">标准输入（可选）<textarea v-model="scriptInput" rows="3"></textarea></label><div class="form-actions"><button class="primary" :disabled="busy || !detail.view.enabled || !script">申请运行</button></div></form><div v-if="scriptJob?.action?.status === 'PENDING'" class="approval-card"><h3>确认运行技能脚本</h3><pre>{{ JSON.stringify(scriptJob.action.operation, null, 2) }}</pre><div class="form-actions"><button class="primary" :disabled="busy" @click="decideScript('approve')">确认执行</button><button class="secondary" :disabled="busy" @click="decideScript('reject')">拒绝</button></div></div><p v-if="scriptJob?.error" class="error">{{ scriptJob.error }}</p><pre v-if="scriptJob?.result">{{ JSON.stringify(scriptJob.result, null, 2) }}</pre></section>
    </template>
  </main>
</template>
